    i = 0
    while num > 0:
        for _ in range(num // val[i]):
            roman_num += syms[i]
            num -= val[i]
        i += 1
    return roman_num

def roman_to_lowercase(roman_num):
    return roman_num.lower()

def int_to_mini_roman(number):
    roman_num = int_to_roman(number)
    return roman_to_lowercase(roman_num)

